import { FilterDataAccessor } from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
} from 'models/Filters';

import type {
  PerformanceAndBreakdownDeepDiveViewBy,
  PerformanceAndBreakdownWaterfallContextKey,
} from '../types';

const ALL_VALUE = 'All';

function hasSpecificValue(value: FilterValue | undefined): value is string {
  return Boolean(value && value !== ALL_VALUE);
}

function hasSpecificCountry(value: FilterValue | undefined): value is string {
  return Boolean(value && value !== ALL_VALUE && value !== 'ABI');
}

export function getPerformanceAndBreakdownContextKey(
  applied: FilterForm,
  isGlobalZone: boolean,
): PerformanceAndBreakdownWaterfallContextKey {
  if (hasSpecificValue(applied.sku)) {
    return 'sku';
  }

  if (hasSpecificValue(applied.sub_brands)) {
    return 'sub_brand';
  }

  if (hasSpecificValue(applied.brands)) {
    return 'brand';
  }

  if (hasSpecificCountry(applied.country)) {
    return 'country';
  }

  if (!isGlobalZone) {
    return 'country';
  }

  return 'global';
}

export const PERFORMANCE_AND_BREAKDOWN_DEFAULT_VIEW_BY: Record<
  PerformanceAndBreakdownWaterfallContextKey,
  PerformanceAndBreakdownDeepDiveViewBy
> = {
  global: 'country',
  country: 'brand',
  brand: 'sub_brand',
  sub_brand: 'sku',
  sku: 'sku',
};

export function getPerformanceAndBreakdownDefaultViewBy(
  contextKey: PerformanceAndBreakdownWaterfallContextKey,
): PerformanceAndBreakdownDeepDiveViewBy {
  return PERFORMANCE_AND_BREAKDOWN_DEFAULT_VIEW_BY[contextKey];
}

export function isPerformanceAndBreakdownViewByDisabled(
  contextKey: PerformanceAndBreakdownWaterfallContextKey,
): boolean {
  return contextKey !== 'global';
}

function isPerformanceAndBreakdownViewBy(
  value: unknown,
): value is PerformanceAndBreakdownDeepDiveViewBy {
  return (
    value === 'country' ||
    value === 'brand' ||
    value === 'sub_brand' ||
    value === 'sku'
  );
}

export function getPerformanceAndBreakdownActiveViewBy(
  contextKey: PerformanceAndBreakdownWaterfallContextKey,
  activeSubFilterValue: unknown,
): PerformanceAndBreakdownDeepDiveViewBy {
  const defaultViewBy = getPerformanceAndBreakdownDefaultViewBy(contextKey);

  if (isPerformanceAndBreakdownViewByDisabled(contextKey)) {
    return defaultViewBy;
  }

  return isPerformanceAndBreakdownViewBy(activeSubFilterValue)
    ? activeSubFilterValue
    : defaultViewBy;
}

const PERFORMANCE_AND_BREAKDOWN_VIEW_BY_LABELS: Record<
  PerformanceAndBreakdownDeepDiveViewBy,
  string
> = {
  country: 'Country',
  brand: 'Brand',
  sub_brand: 'Sub Brand',
  sku: 'SKU',
};

export function getPerformanceAndBreakdownViewByLabel(
  viewBy: PerformanceAndBreakdownDeepDiveViewBy,
): string {
  return PERFORMANCE_AND_BREAKDOWN_VIEW_BY_LABELS[viewBy];
}

function resetBrandHierarchyFilters(
  updateForm: (key: string, value: FilterValue) => void,
): void {
  updateForm('brands', null);
  updateForm('sub_brands', null);
  updateForm('sku', null);
}

type UpdateFormFn = (key: string, value: FilterValue) => void;

function setOrClearFilter(
  updateForm: UpdateFormFn,
  key: string,
  currentValue: FilterValue | undefined,
  nextValue: string,
): void {
  updateForm(key, currentValue === nextValue ? null : nextValue);
}

function handleCountryWaterfallBarClick(
  filterValue: string,
  applied: FilterForm,
  dataFilters: FilterDataStructure | undefined,
  updateForm: UpdateFormFn,
): void {
  if (applied.country === filterValue) {
    updateForm('country', null);
    updateForm('zone', 'ABI');
    resetBrandHierarchyFilters(updateForm);
    return;
  }

  if (dataFilters) {
    const zoneOption = FilterDataAccessor.getInstance().getZoneByCountry(
      dataFilters,
      filterValue,
    );

    if (zoneOption?.value) {
      updateForm('zone', zoneOption.value);
    }
  }

  updateForm('country', filterValue);
  resetBrandHierarchyFilters(updateForm);
}

function handleBrandWaterfallBarClick(
  filterValue: string,
  applied: FilterForm,
  _dataFilters: FilterDataStructure | undefined,
  updateForm: UpdateFormFn,
): void {
  setOrClearFilter(updateForm, 'brands', applied.brands, filterValue);
  updateForm('sub_brands', null);
  updateForm('sku', null);
}

function handleSubBrandWaterfallBarClick(
  filterValue: string,
  applied: FilterForm,
  _dataFilters: FilterDataStructure | undefined,
  updateForm: UpdateFormFn,
): void {
  setOrClearFilter(updateForm, 'sub_brands', applied.sub_brands, filterValue);
  updateForm('sku', null);
}

function handleSkuWaterfallBarClick(
  filterValue: string,
  applied: FilterForm,
  _dataFilters: FilterDataStructure | undefined,
  updateForm: UpdateFormFn,
): void {
  setOrClearFilter(updateForm, 'sku', applied.sku, filterValue);
}

const WATERFALL_BAR_CLICK_HANDLERS: Record<
  PerformanceAndBreakdownDeepDiveViewBy,
  (
    filterValue: string,
    applied: FilterForm,
    dataFilters: FilterDataStructure | undefined,
    updateForm: UpdateFormFn,
  ) => void
> = {
  country: handleCountryWaterfallBarClick,
  brand: handleBrandWaterfallBarClick,
  sub_brand: handleSubBrandWaterfallBarClick,
  sku: handleSkuWaterfallBarClick,
};

export interface PerformanceAndBreakdownWaterfallBarClickParams {
  index: number;
  filterValues?: (string | null)[];
  viewBy: PerformanceAndBreakdownDeepDiveViewBy;
  applied: FilterForm;
  dataFilters?: FilterDataStructure;
  updateForm: (key: string, value: FilterValue) => void;
  apply: () => void;
  disabledIndexes: number[];
}

export function handlePerformanceAndBreakdownWaterfallBarClick({
  index,
  filterValues,
  viewBy,
  applied,
  dataFilters,
  updateForm,
  apply,
  disabledIndexes,
}: PerformanceAndBreakdownWaterfallBarClickParams): void {
  if (disabledIndexes.includes(index)) {
    return;
  }

  const filterValue = filterValues?.[index];
  if (!filterValue) {
    return;
  }

  WATERFALL_BAR_CLICK_HANDLERS[viewBy](
    filterValue,
    applied,
    dataFilters,
    updateForm,
  );
  apply();
}
